package com.ghiles.quizubuntu;
import java.util.*;
/** Questions authored from the six attached S03 documents; each correction identifies its source. */
final class S03QuizBank {
    static List<MainActivity.Question> questions() {
        List<MainActivity.Question> out=new ArrayList<>();
        out.add(new MainActivity.Question(1,"Utilisateurs","Affiche les comptes Linux avec cat.",0,"S03 — Droits des utilisateurs sous Linux 1 — Chaque ligne décrit un compte, son UID, son groupe primaire, son home et son shell.","cat /etc/passwd","cat /etc/passwd").written("Commande à écrire","cat /etc/passwd"));
        out.add(new MainActivity.Question(1,"Utilisateurs","Affiche la base des groupes avec cat.",0,"S03 — Droits des utilisateurs sous Linux 1 — Le dernier champ contient les membres supplémentaires ; le groupe primaire est aussi indiqué dans passwd.","cat /etc/group","cat /etc/group").written("Commande à écrire","cat /etc/group"));
        out.add(new MainActivity.Question(2,"Utilisateurs","En tant que root, crée wilder avec son dossier personnel et Bash.",0,"S03 — Droits des utilisateurs sous Linux 1 — -m crée le home ; -s choisit le shell. Le mot de passe se définit ensuite avec passwd.","useradd -m -s /bin/bash wilder","useradd -m -s /bin/bash wilder").written("Commande à écrire","useradd -m -s /bin/bash wilder","sudo useradd -m -s /bin/bash wilder"));
        out.add(new MainActivity.Question(2,"Utilisateurs","En tant que root, lance le changement du mot de passe de wilder.",0,"S03 — Droits des utilisateurs sous Linux 1 — Sur Linux, deux saisies masquées sont demandées. Le simulateur pédagogique ne stocke aucun mot de passe.","passwd wilder","passwd wilder").written("Commande à écrire","passwd wilder","sudo passwd wilder"));
        out.add(new MainActivity.Question(2,"Utilisateurs","En tant que root, crée le groupe groupetest.",0,"S03 — Droits des utilisateurs sous Linux 1 — Créer le groupe ne lui ajoute pas automatiquement les utilisateurs.","groupadd groupetest","groupadd groupetest").written("Commande à écrire","groupadd groupetest","addgroup groupetest","sudo groupadd groupetest"));
        out.add(new MainActivity.Question(3,"Utilisateurs","Ajoute wilder à groupetest SANS perdre ses autres groupes secondaires.",0,"S03 — Droits des utilisateurs sous Linux 1 — -G définit la liste secondaire ; -a ajoute à cette liste au lieu de la remplacer.","usermod -aG groupetest wilder","usermod -aG groupetest wilder").written("Corriger une commande","usermod -aG groupetest wilder","usermod -a -G groupetest wilder","sudo usermod -aG groupetest wilder"));
        out.add(new MainActivity.Question(2,"Utilisateurs","Affiche UID, GID primaire et groupes de wilder.",0,"S03 — Droits des utilisateurs sous Linux 1 — Le GID primaire et la liste des groupes répondent à deux questions différentes.","id wilder","id wilder").written("Commande à écrire","id wilder"));
        out.add(new MainActivity.Question(2,"Utilisateurs","En tant que root, adopte le contexte utilisateur de wilder sans demander une session login.",0,"S03 — Droits des utilisateurs sous Linux 1 — su change de contexte ; su - charge aussi un environnement de connexion.","su wilder","su wilder").written("Commande à écrire","su wilder"));
        out.add(new MainActivity.Question(1,"Utilisateurs","Quelle commande vérifie ton identité effective ?",0,"S03 — Droits des utilisateurs sous Linux 1 — Elle est utile après su et dans l’expérience du binaire SUID.","whoami","whoami").written("Commande à écrire","whoami"));
        out.add(new MainActivity.Question(2,"Utilisateurs","Reviens à la session précédente après su wilder.",0,"S03 — Droits des utilisateurs sous Linux 1 — exit ferme le shell lancé par su. Cela ne supprime pas le compte.","exit","exit").written("Commande à écrire","exit"));
        out.add(new MainActivity.Question(2,"Utilisateurs","Dans /etc/passwd, x est-il le mot de passe en clair ?",1,"S03 — Droits des utilisateurs sous Linux 1 — Les mots de passe sont représentés par des empreintes dans shadow, pas en clair dans passwd.","wilder:x:1001:1001::/home/wilder:/bin/bash","Oui","Non, il renvoie au stockage protégé dans /etc/shadow","Il signifie compte supprimé"));
        out.add(new MainActivity.Question(3,"Utilisateurs","Piège : quelle commande préserve les groupes secondaires existants en ajoutant groupetest ?",2,"S03 — Droits des utilisateurs sous Linux 1 — Il faut usermod -aG groupetest wilder ; sans -a, la liste secondaire est remplacée.","usermod -aG groupetest wilder","usermod -G groupetest wilder","groupadd groupetest","Aucune de ces réponses"));
        out.add(new MainActivity.Question(1,"Permissions","Dans -rw-r--r--, combien de droits d’écriture le groupe possède-t-il ? Réponds 0 ou 1.",0,"S03 — Droits des utilisateurs sous Linux 2 — Le triplet central est r-- : lecture seulement.","-rw-r--r--  ubuntu ubuntu  notes.txt","0").written("Lire une sortie","0"));
        out.add(new MainActivity.Question(2,"Permissions","Donne rwx au propriétaire, rx au groupe et aucun droit aux autres sur test.txt, en notation symbolique.",0,"S03 — Droits des utilisateurs sous Linux 2 — u, g et o désignent propriétaire, groupe et autres. = remplace le triplet.","chmod u=rwx,g=rx,o= test.txt","chmod u=rwx,g=rx,o= test.txt").written("Commande à écrire","chmod u=rwx,g=rx,o= test.txt"));
        out.add(new MainActivity.Question(2,"Permissions","Donne rwx au propriétaire, r au groupe et rien aux autres sur test.txt, en octal.",0,"S03 — Droits des utilisateurs sous Linux 2 — 7=4+2+1, 4=lecture et 0=aucun droit.","chmod 740 test.txt","chmod 740 test.txt").written("Commande à écrire","chmod 740 test.txt"));
        out.add(new MainActivity.Question(2,"Permissions","Rends confidentiel.txt lisible et modifiable uniquement par son propriétaire.",0,"S03 — Droits des utilisateurs sous Linux 2 — 600 correspond à rw------- ; les autres classes n’ont aucun accès.","chmod 600 confidentiel.txt","chmod 600 confidentiel.txt").written("Commande à écrire","chmod 600 confidentiel.txt"));
        out.add(new MainActivity.Question(2,"Permissions","Rends partage.txt lisible par tous et modifiable par personne via ses bits de mode.",0,"S03 — Droits des utilisateurs sous Linux 2 — Chaque triplet vaut 4. Root conserve ses privilèges ; les bits ne retirent pas ses capacités.","chmod 444 partage.txt","chmod 444 partage.txt").written("Commande à écrire","chmod 444 partage.txt"));
        out.add(new MainActivity.Question(2,"Permissions","Applique rwxr-xr-x à executable.sh en octal.",0,"S03 — Droits des utilisateurs sous Linux 2 — Le propriétaire a 7 ; groupe et autres ont 5=lecture+exécution.","chmod 755 executable.sh","chmod 755 executable.sh").written("Commande à écrire","chmod 755 executable.sh"));
        out.add(new MainActivity.Question(2,"Permissions","Retire uniquement ton droit x de propriétaire sur testdir.",0,"S03 — Droits des utilisateurs sous Linux 2 — Sans x, le propriétaire ne peut pas traverser le dossier, même s’il conserve r.","chmod u-x testdir","chmod u-x testdir").written("Commande à écrire","chmod u-x testdir"));
        out.add(new MainActivity.Question(3,"Permissions","Un dossier a r mais pas x pour toi. Que garantit r ?",2,"S03 — Droits des utilisateurs sous Linux 2 — Lire les noms et traverser un dossier sont deux droits différents.","chmod u=r testdir\nls testdir\ncd testdir # refusé","Pouvoir entrer avec cd","Pouvoir lire le contenu de chaque fichier","Pouvoir lister les noms, sans garantir l’accès aux fichiers"));
        out.add(new MainActivity.Question(3,"Permissions","Avec sudo, affecte test2.txt au propriétaire root et au groupe groupetest.",0,"S03 — Droits des utilisateurs sous Linux 2 — Le compte et le groupe doivent exister. Le séparateur est un deux-points.","sudo chown root:groupetest test2.txt","sudo chown root:groupetest test2.txt").written("Commande à écrire","sudo chown root:groupetest test2.txt"));
        out.add(new MainActivity.Question(2,"Permissions","Tu es autorisé à le faire : change seulement le groupe de test2.txt en groupetest.",0,"S03 — Droits des utilisateurs sous Linux 2 — chgrp laisse le propriétaire inchangé.","chgrp groupetest test2.txt","chgrp groupetest test2.txt").written("Commande à écrire","chgrp groupetest test2.txt","sudo chgrp groupetest test2.txt"));
        out.add(new MainActivity.Question(3,"Permissions","Avec sudo, applique root:groupetest à mondossier ET son contenu.",0,"S03 — Droits des utilisateurs sous Linux 2 — -R applique récursivement le changement aux descendants.","sudo chown -R root:groupetest mondossier","sudo chown -R root:groupetest mondossier").written("Commande à écrire","sudo chown -R root:groupetest mondossier"));
        out.add(new MainActivity.Question(3,"Permissions","Piège : laquelle modifie les permissions du contenu de mondossier récursivement ?",2,"S03 — Droits des utilisateurs sous Linux 2 — chmod sans -R ne modifie que le dossier ; chown change le propriétaire, pas les droits rwx.","chmod -R 750 mondossier","chmod 750 mondossier","chown -R root mondossier","Aucune de ces réponses"));
        out.add(new MainActivity.Question(2,"ACL et droits spéciaux","Affiche le masque de création courant.",0,"S03 — Droits des utilisateurs sous Linux 3 — Le masque s’applique aux nouvelles créations ; il ne modifie pas les fichiers déjà présents.","umask","umask").written("Commande à écrire","umask"));
        out.add(new MainActivity.Question(3,"ACL et droits spéciaux","Fixe le masque à 077 pour la session.",0,"S03 — Droits des utilisateurs sous Linux 3 — Les nouveaux fichiers obtiennent typiquement 600 et les dossiers 700.","umask 077","umask 077").written("Commande à écrire","umask 077"));
        out.add(new MainActivity.Question(3,"ACL et droits spéciaux","Avec umask 077, quel mode octal a un nouveau fichier créé par touch ?",0,"S03 — Droits des utilisateurs sous Linux 3 — On calcule 0666 & ~0077. Un fichier ordinaire ne reçoit pas x par défaut.","umask 077\ntouch secret.txt\nls -l secret.txt","600").written("Prédire le résultat","600"));
        out.add(new MainActivity.Question(4,"ACL et droits spéciaux","Avec umask 033, quel mode octal a un nouveau fichier ordinaire ?",0,"S03 — Droits des utilisateurs sous Linux 3 — Piège du support : le masque retire des bits. 0666 & ~0033 = 0644 ; une soustraction arithmétique donnerait un résultat faux.","umask 033\ntouch note.txt","644").written("Prédire le résultat","644"));
        out.add(new MainActivity.Question(3,"ACL et droits spéciaux","Ajoute SGID au dossier partage-equipe, sans changer ses droits rwx.",0,"S03 — Droits des utilisateurs sous Linux 3 — Les nouvelles entrées héritent du groupe du dossier.","chmod g+s partage-equipe","chmod g+s partage-equipe").written("Commande à écrire","chmod g+s partage-equipe"));
        out.add(new MainActivity.Question(3,"ACL et droits spéciaux","Ajoute le sticky bit à partage-equipe.",0,"S03 — Droits des utilisateurs sous Linux 3 — Dans un dossier partagé, root, le propriétaire du dossier ou le propriétaire du fichier peuvent le supprimer ; les autres sont bloqués.","chmod +t partage-equipe","chmod +t partage-equipe").written("Commande à écrire","chmod +t partage-equipe","chmod a+t partage-equipe","chmod o+t partage-equipe"));
        out.add(new MainActivity.Question(4,"ACL et droits spéciaux","Ajoute SUID au binaire mon-whoami.",0,"S03 — Droits des utilisateurs sous Linux 3 — L’expérience du PDF porte sur un binaire exécutable. Linux n’applique généralement pas SUID aux scripts shell.","chmod u+s mon-whoami","chmod u+s mon-whoami").written("Commande à écrire","chmod u+s mon-whoami"));
        out.add(new MainActivity.Question(3,"ACL et droits spéciaux","Retire SUID à mon-whoami.",0,"S03 — Droits des utilisateurs sous Linux 3 — -s retire seulement le bit spécial de la classe u.","chmod u-s mon-whoami","chmod u-s mon-whoami").written("Commande à écrire","chmod u-s mon-whoami"));
        out.add(new MainActivity.Question(4,"ACL et droits spéciaux","Un binaire whoami appartient à root, a SUID et reste exécutable. Wilder le lance : quelle identité effective affiche-t-il ?",0,"S03 — Droits des utilisateurs sous Linux 3 — SUID adopte l’identité effective du propriétaire du binaire.","sudo chown root mon-whoami\nsudo chmod u+s mon-whoami\n./mon-whoami","root").written("Prédire le résultat","root"));
        out.add(new MainActivity.Question(3,"ACL et droits spéciaux","Donne à wilder une ACL de lecture sur fichier.txt. Tu es propriétaire ou root.",0,"S03 — Droits des utilisateurs sous Linux 3 — Cette entrée nommée ne change ni le propriétaire ni le groupe du fichier.","setfacl -m u:wilder:r fichier.txt","setfacl -m u:wilder:r fichier.txt").written("Commande à écrire","setfacl -m u:wilder:r fichier.txt","setfacl -m u:wilder:r-- fichier.txt"));
        out.add(new MainActivity.Question(3,"ACL et droits spéciaux","Affiche les ACL de fichier.txt.",0,"S03 — Droits des utilisateurs sous Linux 3 — Le masque limite les permissions effectives des utilisateurs nommés et de la classe groupe.","getfacl fichier.txt","getfacl fichier.txt").written("Commande à écrire","getfacl fichier.txt"));
        out.add(new MainActivity.Question(3,"ACL et droits spéciaux","Retire l’entrée ACL nommée de wilder sur fichier.txt.",0,"S03 — Droits des utilisateurs sous Linux 3 — -x retire l’entrée ; -m l’ajoute ou la modifie.","setfacl -x u:wilder fichier.txt","setfacl -x u:wilder fichier.txt").written("Commande à écrire","setfacl -x u:wilder fichier.txt"));
        out.add(new MainActivity.Question(4,"ACL et droits spéciaux","Autorise invite à lister ET traverser partage-equipe par ACL.",0,"S03 — Droits des utilisateurs sous Linux 3 — Sur un dossier, r liste et x permet la traversée. r seul ne suffit pas à lire les fichiers à l’intérieur.","setfacl -m u:invite:rx partage-equipe","setfacl -m u:invite:rx partage-equipe").written("Commande à écrire","setfacl -m u:invite:rx partage-equipe","setfacl -m u:invite:r-x partage-equipe"));
        out.add(new MainActivity.Question(3,"ACL et droits spéciaux","En tant que root, ajoute wilder au groupe sudo sans enlever ses autres groupes.",0,"S03 — Droits des utilisateurs sous Linux 3 — Sur Ubuntu, le groupe sudo est habituellement autorisé par sudoers.","usermod -aG sudo wilder","usermod -aG sudo wilder").written("Commande à écrire","usermod -aG sudo wilder","usermod -a -G sudo wilder"));
        out.add(new MainActivity.Question(3,"ACL et droits spéciaux","Lis la configuration sudoers sans l’éditer.",0,"S03 — Droits des utilisateurs sous Linux 3 — L’éditeur adapté pour une modification serait visudo, qui valide la syntaxe.","sudo cat /etc/sudoers","sudo cat /etc/sudoers").written("Commande à écrire","sudo cat /etc/sudoers"));
        out.add(new MainActivity.Question(4,"ACL et droits spéciaux","Recherche les chemins qui ont le bit SUID en ignorant les erreurs sur stderr.",0,"S03 — Droits des utilisateurs sous Linux 3 — Le tiret devant 4000 recherche tous les bits indiqués ; 2 désigne stderr.","find / -perm -4000 2>/dev/null","find / -perm -4000 2>/dev/null").written("Commande à écrire","find / -perm -4000 2>/dev/null"));
        out.add(new MainActivity.Question(4,"ACL et droits spéciaux","Piège : quel mécanisme empêche à lui seul de supprimer le fichier d’un autre dans un dossier partagé inscriptible ?",2,"S03 — Droits des utilisateurs sous Linux 3 — Le mécanisme attendu est le sticky bit du dossier. SGID choisit le groupe, et umask les droits de création.","chmod +t partage-equipe","SGID","Une umask 077","Aucune de ces réponses"));
        out.add(new MainActivity.Question(1,"VirtualBox","Liste les VM enregistrées.",0,"S03 — Création de VM en CLI dans VirtualBox — Chaque ligne associe un nom à un UUID.","VBoxManage list vms","VBoxManage list vms").written("Commande à écrire","VBoxManage list vms","vboxmanage list vms"));
        out.add(new MainActivity.Question(2,"VirtualBox","Liste uniquement les VM démarrées.",0,"S03 — Création de VM en CLI dans VirtualBox — Une liste vide n’est pas une erreur : aucune VM n’est démarrée.","VBoxManage list runningvms","VBoxManage list runningvms").written("Commande à écrire","VBoxManage list runningvms","vboxmanage list runningvms"));
        out.add(new MainActivity.Question(2,"VirtualBox","Affiche les informations d’Ubuntu10.",0,"S03 — Création de VM en CLI dans VirtualBox — Le nom ou l’UUID peut identifier une VM.","VBoxManage showvminfo Ubuntu10","VBoxManage showvminfo Ubuntu10").written("Commande à écrire","VBoxManage showvminfo Ubuntu10","vboxmanage showvminfo Ubuntu10"));
        out.add(new MainActivity.Question(3,"VirtualBox","Crée et enregistre une VM Ubuntu10 de type Ubuntu_64.",0,"S03 — Création de VM en CLI dans VirtualBox — createvm crée la configuration ; cela n’installe pas encore Ubuntu.","VBoxManage createvm --name Ubuntu10 --ostype Ubuntu_64 --register","VBoxManage createvm --name Ubuntu10 --ostype Ubuntu_64 --register").written("Commande à écrire","VBoxManage createvm --name Ubuntu10 --ostype Ubuntu_64 --register","vboxmanage createvm --name Ubuntu10 --ostype Ubuntu_64 --register"));
        out.add(new MainActivity.Question(2,"VirtualBox","--memory 2048 représente combien de Gio de RAM ? Réponds avec un nombre.",0,"S03 — Création de VM en CLI dans VirtualBox — Correction du support : 2048 Mo de RAM, soit 2 Gio, et non 2048 Go.","VBoxManage modifyvm Ubuntu10 --memory 2048","2").written("Prédire le résultat","2"));
        out.add(new MainActivity.Question(3,"VirtualBox","Configure la carte réseau 1 d’Ubuntu10 en NAT.",0,"S03 — Création de VM en CLI dans VirtualBox — Le mode NAT est un réglage de réseau de la VM.","VBoxManage modifyvm Ubuntu10 --nic1 nat","VBoxManage modifyvm Ubuntu10 --nic1 nat").written("Commande à écrire","VBoxManage modifyvm Ubuntu10 --nic1 nat","vboxmanage modifyvm Ubuntu10 --nic1 nat"));
        out.add(new MainActivity.Question(3,"VirtualBox","Démarre Ubuntu10 en mode graphique.",0,"S03 — Création de VM en CLI dans VirtualBox — Dans l’application, seul l’état est simulé ; sur un hôte VirtualBox, cette commande démarre réellement la VM.","VBoxManage startvm Ubuntu10 --type gui","VBoxManage startvm Ubuntu10 --type gui").written("Commande à écrire","VBoxManage startvm Ubuntu10 --type gui","vboxmanage startvm Ubuntu10 --type gui"));
        out.add(new MainActivity.Question(3,"VirtualBox","Liste les snapshots de la VM glpi.",0,"S03 — Création de VM en CLI dans VirtualBox — Un snapshot permet de repérer un état ; la liste ne restaure rien.","VBoxManage snapshot glpi list","VBoxManage snapshot glpi list").written("Commande à écrire","VBoxManage snapshot glpi list","vboxmanage snapshot glpi list"));
        out.add(new MainActivity.Question(4,"VirtualBox","Quelle étape relie un disque déjà créé à la VM ?",1,"S03 — Création de VM en CLI dans VirtualBox — createmedium crée le média ; storagectl crée le contrôleur ; storageattach raccorde le média au contrôleur.","VBoxManage storageattach Ubuntu10 --storagectl \"SATA Controller\" --port 0 --device 0 --type hdd --medium disque.vmdk","createmedium","storageattach","list vms"));
        out.add(new MainActivity.Question(4,"VirtualBox","Classe : 1=storageattach, 2=createvm, 3=storagectl, 4=createmedium, 5=startvm. Utilise cet ordre où le contrôleur précède la création du disque.",0,"S03 — Création de VM en CLI dans VirtualBox — La VM, son contrôleur et le média doivent exister avant le raccordement et le démarrage.","createvm → storagectl → createmedium → storageattach → startvm","2 3 4 1 5").written("Ordre à rétablir","2 3 4 1 5"));
        out.add(new MainActivity.Question(4,"VirtualBox","Dans le script du support, que signifie ${3:-1} ?",1,"S03 — Création de VM en CLI dans VirtualBox — Cette expansion fournit le nombre de VM par défaut. $1 et $2 correspondent au nom et à la RAM.","num_vms=${3:-1}","Toujours le troisième argument","Le troisième argument, ou 1 s’il est absent ou vide","Une soustraction"));
        out.add(new MainActivity.Question(4,"VirtualBox","Pourquoi écrire \"$iso_path\" dans le script ?",0,"S03 — Création de VM en CLI dans VirtualBox — Les guillemets empêchent la séparation en plusieurs arguments. Ils sont aussi nécessaires autour des noms et chemins variables.","--medium \"$iso_path\"","Pour conserver un chemin contenant des espaces comme un seul argument","Pour augmenter la RAM","Pour convertir l’ISO en VMDK"));
        out.add(new MainActivity.Question(3,"VirtualBox","Quelle sous-commande VBoxManage copie le disque modèle du support ? Donne seulement son nom.",0,"S03 — Création de VM en CLI dans VirtualBox — Copier le média crée un disque distinct pour la nouvelle VM.","VBoxManage clonemedium disk \"template.vmdk\" \"copie.vmdk\" --format VMDK","clonemedium").written("Diagnostic","clonemedium"));
        out.add(new MainActivity.Question(1,"Windows","Dans CMD Windows, liste le dossier courant.",0,"S03 — Le terminal sous Windows — dir est la commande étudiée sous Windows ; ls est la commande de référence du cours Linux.","dir","dir").written("Commande à écrire","dir"));
        out.add(new MainActivity.Question(1,"Windows","Dans CMD Windows, entre dans le sous-dossier Secured.",0,"S03 — Le terminal sous Windows — cd change le dossier ; dir en affiche le contenu.","cd Secured","cd Secured").written("Commande à écrire","cd Secured"));
        out.add(new MainActivity.Question(1,"Windows","Dans CMD Windows, remonte au dossier parent.",0,"S03 — Le terminal sous Windows — .. désigne le parent, sous Windows comme sous Linux.","cd ..","cd ..").written("Commande à écrire","cd .."));
        out.add(new MainActivity.Question(2,"Windows","Quel chemin désigne un dossier Windows à partir de la racine du lecteur C: ?",0,"S03 — Le terminal sous Windows — C:\\ commence à la racine du lecteur ; C:Secured est relatif au dossier courant de ce lecteur.","cd C:\\Users\\wilder\\Secured","C:\\Users\\wilder\\Secured","/home/wilder/Secured","C:Secured"));
        out.add(new MainActivity.Question(2,"Windows","Dans le challenge Secured, qui doit conserver le contrôle total ?",1,"S03 — Le terminal sous Windows — Le challenge demande la lecture pour les utilisateurs ordinaires et tous les droits pour l’administrateur. Les ACL NTFS se configurent dans le contexte Windows.","Secured : utilisateurs → lecture ; administrateur → contrôle total","Tout le monde","L’administrateur","Personne"));
        out.add(new MainActivity.Question(2,"Windows","NTFS et une convention de chemin désignent-ils la même chose ?",1,"S03 — Le terminal sous Windows — Le support distingue système de fichiers et convention de nommage. Windows peut aussi utiliser d’autres systèmes de fichiers.","C:\\Windows\\System32","Oui","Non : NTFS organise le stockage, le chemin désigne un emplacement","NTFS est une commande"));
        out.add(new MainActivity.Question(1,"VirtualBox","D’après le document S03 — Exercices, après quel cours pratiquer la création de VM en CLI ?",0,"S03 — Exercices (DOCX) — Le DOCX organise les supports : gestion des utilisateurs et terminal Windows avant S03 ; VirtualBox de préférence après La Virtualisation.","S03 — Exercices : La Virtualisation → atelier VirtualBox","La Virtualisation","La résolution des conflits Git","Aucun cours indiqué"));
        return out;
    }
}
